with exploded as (select id, service, level, key, attr_value from app_logs lateral view outer explode(context) x as key, attr_value), kept_keys as (select level, service from exploded except select level, service from app_logs where status_code < 296), kept_rows as (select s.* from exploded s inner join kept_keys k on s.level = k.level and s.service = k.service), filtered as (select id, service, level, key, attr_value, case when service = 'search' then 1 else 0 end as is_search from kept_rows where key is distinct from 'region'), metrics as (select service, level, key, attr_value, is_search, percent_rank() over (partition by key, service order by is_search desc nulls first) as is_search_percent_rank from filtered where level in ('INFO', 'WARN', 'ERROR')) select service, percentile_approx(is_search_percent_rank, array(0.25, 0.5, 0.75)) as is_search_percent_rank_quartiles, approx_percentile(is_search_percent_rank, array(0.25, 0.5, 0.75)) as is_search_percent_rank_quartiles_2, size(collect_set(key)) as num_keys from metrics group by 1 order by num_keys desc nulls last;
